 function destroyBuilding(b){b.hp=0;shake=7;burst(b.x,b.y,'#ffb847',25);if(b.type==='hq'){toast('🏆 VILLAIN HQ DESTROYED! CITY SAVED!');finish(true)}else if(buildings.every(z=>z.hp<=0))finish(true);updateUI()}
 function finish(win){if(state!=='battle')return;state='over';const pct=100*(totalHP-buildings.reduce((n,b)=>n+Math.max(0,b.hp),0))/totalHP;let stars=(pct>=50?1:0)+(pct>=75?1:0)+(buildings[0].hp<=0?1:0);$('overlay').style.display='flex';$('overlay').querySelector('.big').textContent=win?'🏆✨':'💥🦸';$('overlay').querySelector('h1').textContent=win?'CITY SAVED!':'TIME’S UP!';$('overlay').querySelector('p').innerHTML=`Raid complete! You earned <b style="color:#ffd85b">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</b><br>${Math.floor(pct)}% base destroyed · Loot secured!<br><b>Ready to lead another raid?</b>`;$('start').textContent='PLAY AGAIN';}
 function update(dt){if(state==='battle'){time-=dt;elapsed+=dt;if(time<=0){time=0;finish(false)}if(time<20)$('timer').classList.add('urgent');$('timer').textContent=`${Math.floor(time/60)}:${String(Math.ceil(time%60)).padStart(2,'0')}`;for(const b of buildings){if(b.hp<=0)continue;b.flash=Math.max(0,b.flash-dt);if(['cannon','tower'].includes(b.type)){b.attack-=dt;if(b.attack<=0){let range=b.type==='tower'?220:180;let target=troops.filter(t=>t.hp>0&&Math.hypot(t.x-b.x,t.y-b.y)<range).sort((a,z)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(z.x-b.x,z.y-b.y))[0];if(target){projectiles.push({x:b.x,y:b.y-12,target,spd:b.type==='tower'?200:270,color:b.type==='tower'?'#ff3bdf':'#ffb452',damage:b.type==='tower'?17:13});b.attack=b.type==='tower'?.7:1.15}else b.attack=.25}}}
 for(const t of troops){if(t.hp<=0)continue;t.flash=Math.max(0,t.flash-dt);t.attack-=dt;let b=targetFor(t);if(!b)continue;let dx=b.x-t.x,dy=b.y-t.y,d=Math.hypot(dx,dy),s=specs[t.type],reach=s.range+(b.w*.35);t.dir=Math.atan2(dy,dx);if(d>reach){let move=Math.min(d-reach,s.speed*dt);t.x+=dx/d*move;t.y+=dy/d*move;t.walk+=dt*s.speed/13}else if(t.attack<=0){if(t.type==='blaster')projectiles.push({x:t.x,y:t.y-12,target:b,spd:300,color:'#74eaff',damage:s.damage,hero:true});else{b.hp-=s.damage;b.flash=.14;burst(b.x+(Math.random()-.5)*b.w*.5,b.y+(Math.random()-.5)*b.h*.4,colors[t.type],4);if(b.hp<=0)destroyBuilding(b)}t.attack=s.rate} }
-for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];if(!p.target||p.target.hp<=0||p.target.hp===undefined&&p.target.hp<=0){projectiles.splice(i,1);continue}let dx=p.target.x-p.x,dy=(p.target.y-8)-p.y,d=Math.hypot(dx,dy);if(d<p.spd*dt+7){if(p.hero){p.target.hp-=p.damage;p.target.flash=.12;if(p.target.hp<=0)destroyBuilding(p.target);else burst(p.target.x,p.target.y,p.color,3)}else{p.target.hp-=p.damage;p.target.flash=.16;burst(p.target.x,p.target.y,p.color,5);if(p.target.hp<=0){p.target.hp=1;/* buildings don't take damage from defense */p.target.hp=p.target.hp} }projectiles.splice(i,1)}else{p.x+=dx/d*p.spd*dt;p.y+=dy/d*p.spd*dt}}
+for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];if(!p.target||p.target.hp<=0||p.target.hp===undefined&&p.target.hp<=0){projectiles.splice(i,1);continue}let dx=p.target.x-p.x,dy=(p.target.y-8)-p.y,d=Math.hypot(dx,dy);if(d<p.spd*dt+7){if(p.hero){p.target.hp-=p.damage;p.target.flash=.12;if(p.target.hp<=0)destroyBuilding(p.target);else burst(p.target.x,p.target.y,p.color,3)}else{p.target.hp=Math.max(0,p.target.hp-p.damage);p.target.flash=.16;burst(p.target.x,p.target.y,p.color,5)}projectiles.splice(i,1)}else{p.x+=dx/d*p.spd*dt;p.y+=dy/d*p.spd*dt}}
 for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt}particles=particles.filter(p=>p.life>0);troops=troops.filter(t=>t.hp>0||t.hp===0);if(elapsed%0.35<dt)updateUI();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}}}
 function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
 function drawGround(){ctx.fillStyle='#78b761';ctx.fillRect(0,0,W,H);ctx.fillStyle='#8cc66b';for(let y=0;y<H;y+=48)for(let x=0;x<W;x+=48){if((x/48+y/48)%2===0){ctx.globalAlpha=.12;ctx.fillRect(x,y,48,48)}}ctx.globalAlpha=1;
 // central base clearing
